/// <summary>
/// Tier 2 is a ten percent discount.
/// </summary>
[SysTestMethod, SysTestCheckInTest]
public void testTierTwoIsTenPercent()
{
    this.assertEquals(10, ConDemoDiscount::rateForTier(2), 'tier 2 must be 10 percent');
